-- Agenda taken from the "Quoi de neuf" and "Les samedis" pages of the original site.
insert into public.news (id, title, excerpt, starts_at, ends_at, featured, status, created_by, updated_by)
values
  ('00000000-0000-4000-8000-000000000201', 'Jeudi 8 octobre : GEM Hors les murs au musée Fabre', 'Après le temps d''accueil habituel de 10 h à 10 h 45 au café « The Little Italy Shop », 4 bis cours Gambetta (à côté de l''arrêt Saint-Denis du tram 3), visite de l''exposition « Le Design selon Pierre Paulin » au musée Fabre. Le GEM prend en charge les billets d''entrée ; pensez à vos justificatifs pour bénéficier des réductions.', '2026-10-08T10:00:00+02:00', '2026-10-08T13:00:00+02:00', true, 'published', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001'),
  ('00000000-0000-4000-8000-000000000208', 'Jeudi 8 octobre : yoga en douceur et écriture poétique', 'L''atelier « yoga en douceur » a lieu à 15 h, puis l''atelier « écriture poétique » avec Mona à 16 h 45.', '2026-10-08T15:00:00+02:00', null, false, 'published', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001'),
  ('00000000-0000-4000-8000-000000000207', 'Mercredi 7 octobre : « Les mots qui volent »', 'L''atelier « Les mots qui volent » a lieu à 15 h.', '2026-10-07T15:00:00+02:00', null, false, 'published', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001'),
  ('00000000-0000-4000-8000-000000000202', 'Mardi 6 octobre : Qi Gong, groupe de parole annulé', 'L''atelier « Qi Gong » a lieu à 14 h 30. Le groupe de parole est exceptionnellement annulé en raison de la séance mensuelle d''analyse de pratique des animatrices, de 15 h à 16 h 45.', '2026-10-06T14:30:00+02:00', null, false, 'published', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001'),
  ('00000000-0000-4000-8000-000000000206', 'Lundi 5 octobre : expression créatrice', 'Le GEM est ouvert par Mona. L''atelier « Expression créatrice » a lieu à 14 h.', '2026-10-05T14:00:00+02:00', null, false, 'published', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001'),
  ('00000000-0000-4000-8000-000000000203', 'Samedi 3 octobre : atelier collage', 'Le GEM est ouvert par Mona. L''atelier collage a lieu à 14 h.', '2026-10-03T14:00:00+02:00', null, false, 'published', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001'),
  ('00000000-0000-4000-8000-000000000205', 'Vendredi 2 octobre : linogravure', 'L''atelier « linogravure » a lieu à 14 h.', '2026-10-02T14:00:00+02:00', null, false, 'published', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001'),
  ('00000000-0000-4000-8000-000000000204', 'Les samedis d''août', 'Les samedis, le GEM est ouvert par un adhérent porteur de clés ; une animatrice est présente un samedi par mois. En août : ouverture par un adhérent les 1er, 15, 22 et 29 août, et par Mona le 8 août.', '2026-08-01T12:00:00+02:00', '2026-08-29T12:00:00+02:00', false, 'published', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001')
on conflict (id) do update set
  title = excluded.title,
  excerpt = excluded.excerpt,
  starts_at = excluded.starts_at,
  ends_at = excluded.ends_at,
  featured = excluded.featured;

-- The six fixed site pages, editable in the admin (same content as migration 20261016170000).
insert into public.pages (slug, title, summary, content, status, published_at, created_by, updated_by)
select v.slug, v.title, v.summary, v.content, 'published', now(), '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001'
from (values
  ('qui-sommes-nous', 'Le GEM Janus34', 'Janus34 est un Groupe d''Entraide Mutuelle et une association loi 1901 fondée en 2006 à Montpellier. Ses adhérents, tous concernés par des troubles psychiques, en font un lieu de rencontre, d''entraide et de partage.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Qu''est-ce qu''un Groupe d''Entraide Mutuelle ?"}]},{"type":"paragraph","content":[{"type":"text","text":"Un Groupe d''Entraide Mutuelle, ou GEM, est une association de personnes qui vivent des difficultés psychiques et se retrouvent pour s''entraider, partager des activités et rompre l''isolement. On y vient librement, à son rythme."}]},{"type":"paragraph","content":[{"type":"text","text":"Les GEM fonctionnent selon un cahier des charges national publié au Journal officiel."}]},{"type":"paragraph","content":[{"type":"text","text":"Cahier des charges des GEM (Légifrance)","marks":[{"type":"link","attrs":{"href":"https://www.legifrance.gouv.fr/jorf/id/JORFTEXT000038792936","target":null,"rel":null,"class":null}}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Janus34 depuis 2006"}]},{"type":"paragraph","content":[{"type":"text","text":"Janus34 a été fondée en 2006 par des personnes et des proches concernés par des troubles bipolaires. L''association s''est donné pour objectif de rompre les solitudes et de favoriser l''entraide, la solidarité et le partage entre ses membres."}]},{"type":"paragraph","content":[{"type":"text","text":"Elle informe et soutient aussi les personnes qui présentent des troubles de l''humeur et d''autres difficultés psychiques."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Pourquoi Janus ?"}]},{"type":"paragraph","content":[{"type":"text","text":"Dans la mythologie romaine, Janus est le dieu des commencements et des fins, des choix, du passage et des portes. Il est représenté avec une face tournée vers le passé et l''autre vers l''avenir."}]},{"type":"paragraph","content":[{"type":"text","text":"Il est fêté le 1er janvier : son mois, Januarius, a donné son nom à janvier."}]},{"type":"paragraph","content":[{"type":"text","text":"Janus sur Wikipédia","marks":[{"type":"link","attrs":{"href":"https://fr.wikipedia.org/wiki/Janus_(mythologie)","target":null,"rel":null,"class":null}}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Ce que nous partageons"}]},{"type":"paragraph","content":[{"type":"text","text":"La vie du GEM repose sur quelques principes simples."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"L''entraide : chacun apporte son expérience et peut s''appuyer sur celle des autres."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Le lien social : se retrouver, discuter, sortir ensemble."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"L''autonomie : la participation aux activités n''est jamais obligatoire."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"La participation : chacun peut prendre part à la vie de l''association."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Une association gérée par ses adhérents"}]},{"type":"paragraph","content":[{"type":"text","text":"Les adhérents de Janus34 sont tous des personnes concernées par des troubles psychiques. Le Conseil d''Administration est uniquement composé d''adhérents : ce sont donc des adhérents qui prennent les décisions de l''association."}]},{"type":"paragraph","content":[{"type":"text","text":"Après un entretien d''accueil, une personne qui découvre le GEM vient d''abord comme visiteur, pendant une dizaine de venues. Son adhésion est ensuite validée par le Conseil d''Administration."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"L''équipe d''animation et les intervenants"}]},{"type":"paragraph","content":[{"type":"text","text":"Une équipe d''animatrices salariées accueille les adhérents et anime une partie des activités. D''autres ateliers sont animés par des intervenants extérieurs professionnels, par des stagiaires ou par des adhérents."}]},{"type":"paragraph","content":[{"type":"text","text":"Le samedi, le GEM est ouvert par un adhérent porteur de clés, et une animatrice est présente un samedi par mois."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Un lieu d''entraide, distinct du soin"}]},{"type":"paragraph","content":[{"type":"text","text":"Janus34 n''est pas une structure de soins et ne remplace pas un suivi médical ou psychologique. L''association n''établit pas de diagnostic et ne délivre pas de traitement."}]},{"type":"paragraph","content":[{"type":"text","text":"Le GEM peut en revanche compléter un parcours de soins en offrant un lieu de rencontre, d''activités et de soutien entre pairs. Des professionnels du CHU de Montpellier sont déjà intervenus au GEM lors de conférences d''information."}]}]}'::jsonb),
  ('activites', 'Activités', 'Ateliers créatifs, activités corporelles douces, groupes d''échange et sorties rythment la semaine à Janus34. Chacun y participe librement, selon ses envies.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Créer et s''exprimer"}]},{"type":"paragraph","content":[{"type":"text","text":"Les ateliers d''expression stimulent l''imagination et la concentration. Ils permettent de se décentrer des difficultés et de s''ouvrir à de nouveaux centres d''intérêt."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Expression créatrice"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"« Les mots qui volent »"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Écriture poétique"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Linogravure"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Collage"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Bouger et prendre l''air"}]},{"type":"paragraph","content":[{"type":"text","text":"Remettre le corps en mouvement aide à retrouver le plaisir de bouger, à reprendre confiance en soi et à relâcher les tensions."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Qi Gong"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Yoga en douceur"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"GEM « Hors les murs » : un temps d''accueil dans un café du centre-ville, puis une visite d''exposition, une balade ou un pique-nique"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Échanger et agir ensemble"}]},{"type":"paragraph","content":[{"type":"text","text":"Les temps d''échange permettent de mieux se connaître, de partager son expérience et d''être soutenu face à la maladie."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Groupe d''échange libre et groupe de parole à thème, en alternance"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Temps collectifs du samedi : goûters, projections de film, repas, pétanque, sorties"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"« Soupe au caillou », chaque dernier jeudi du mois, sur inscription"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Assemblée générale et vie de l''association"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Soutien face à la maladie"}]},{"type":"paragraph","content":[{"type":"text","text":"Ce troisième axe de la démarche de Janus34 aide chacun à mieux vivre avec ses troubles, grâce à l''échange entre pairs et à l''information."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Mieux connaître et comprendre la maladie, et mieux repérer les signes précurseurs"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"S''informer sur le trouble bipolaire d''un point de vue médical, social et psychologique"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Favoriser l''échange entre adhérents"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Soutenir le processus thérapeutique"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Faciliter l''expression des difficultés et des souffrances rencontrées"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Les conférences"}]},{"type":"paragraph","content":[{"type":"text","text":"Des médecins psychiatres et des psychologues du CHU de Montpellier interviennent régulièrement à Janus34 sur des thèmes liés aux troubles psychiques. Ces conférences sont ouvertes à tous, pour mieux connaître et comprendre ces troubles : vous pouvez aussi poser vos questions aux intervenants."}]},{"type":"paragraph","content":[{"type":"text","text":"Les conférences sont sur inscription auprès de l''équipe. En cas d''empêchement, prévenez-nous pour que la place profite à une autre personne. Le programme du cycle 2026-2027 sera annoncé dans les actualités."}]},{"type":"paragraph","content":[{"type":"text","text":"Ces temps d''information ne remplacent pas un suivi personnel par un professionnel de santé."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Un programme qui évolue"}]},{"type":"paragraph","content":[{"type":"text","text":"Le planning évolue au fil du temps. Certaines activités demandent une inscription, comme la « Soupe au caillou » ou les conférences."}]},{"type":"paragraph","content":[{"type":"text","text":"Le planning en vigueur reste la référence pour connaître les jours et les horaires. En cas de doute, appelez l''équipe au 04 67 04 87 68."}]},{"type":"paragraph","content":[{"type":"text","text":"Voir le planning de la semaine","marks":[{"type":"link","attrs":{"href":"/actualites#planning","target":null,"rel":null,"class":null}}]}]}]}'::jsonb),
  ('nous-rejoindre', 'Préparer une première visite', 'Avant une première visite, contactez l''association par téléphone pour convenir d''un premier accueil. Une animatrice vous présentera le GEM et son fonctionnement.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Comment se passe une première visite ?"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Appelez le 04 67 04 87 68 l''après-midi, du lundi au vendredi. Si personne ne répond, laissez un message avec vos coordonnées : l''équipe vous rappellera."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Convenez d''un rendez-vous pour un entretien d''accueil avec une animatrice."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pendant cet entretien, découvrez le lieu, les activités et les règles de vie du GEM, et posez toutes vos questions."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Revenez si vous le souhaitez : pendant une dizaine de venues, vous êtes « visiteur » et découvrez l''association à votre rythme."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Décidez librement d''adhérer. L''adhésion est ensuite validée par le Conseil d''Administration."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"À qui s''adresse Janus34 ?"}]},{"type":"paragraph","content":[{"type":"text","text":"Janus34 accueille des personnes concernées par des troubles psychiques qui souhaitent rompre l''isolement, rencontrer d''autres personnes et partager des activités."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Adresse et transports en commun"}]},{"type":"paragraph","content":[{"type":"text","text":"Janus34 se trouve au 405 rue des Grèzes à Montpellier (34070)."}]},{"type":"paragraph","content":[{"type":"text","text":"En transports en commun, prenez la ligne de bus 11 et descendez à l''arrêt « La Martelle »."}]},{"type":"paragraph","content":[{"type":"text","text":"Voir l''itinéraire sur Google Maps","marks":[{"type":"link","attrs":{"href":"https://www.google.com/maps/search/?api=1&query=405+rue+des+Gr%C3%A8zes+34070+Montpellier","target":null,"rel":null,"class":null}}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Horaires"}]},{"type":"paragraph","content":[{"type":"text","text":"Le GEM ouvre ses portes à 13 h, du lundi au samedi. Le jeudi matin, le GEM « Hors les murs » donne rendez-vous en ville. Le planning des activités précise le programme de chaque jour."}]},{"type":"paragraph","content":[{"type":"text","text":"Voir le planning de la semaine","marks":[{"type":"link","attrs":{"href":"/actualites#planning","target":null,"rel":null,"class":null}}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Sans engagement"}]},{"type":"paragraph","content":[{"type":"text","text":"La première visite n''engage à rien. Vous pouvez découvrir les activités, poser vos questions et prendre le temps de décider. Les règles de vie du GEM, que l''équipe vous présentera, facilitent le vivre ensemble."}]},{"type":"paragraph","content":[{"type":"text","text":"Lire les règles de vie (PDF)","marks":[{"type":"link","attrs":{"href":"/documents/regles-de-vie.pdf","target":null,"rel":null,"class":null}}]}]}]}'::jsonb),
  ('ressources', 'Ressources', 'Des documents et des sites sélectionnés par Janus34 pour mieux comprendre les troubles bipolaires, soutenir un proche et trouver des idées de sorties à Montpellier.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Le rôle de ces ressources"}]},{"type":"paragraph","content":[{"type":"text","text":"Janus34 n''est ni un professionnel de santé ni un service de soins. Les ressources présentées ici ont un rôle d''information générale : elles ne permettent pas d''établir un diagnostic et ne constituent pas des conseils médicaux."}]},{"type":"paragraph","content":[{"type":"text","text":"Elles peuvent aider à mettre des mots sur une expérience, à préparer un échange avec un médecin ou à mieux soutenir un proche."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Repères sur les troubles bipolaires"}]},{"type":"paragraph","content":[{"type":"text","text":"Le trouble bipolaire se manifeste par l''alternance d''épisodes dépressifs et d''épisodes d''excitation de l''humeur, dits hypomaniaques ou maniaques, séparés ou non par des périodes d''humeur stable."}]},{"type":"paragraph","content":[{"type":"text","text":"Les documents à télécharger en bas de page permettent d''approfondir : questions et réponses, guide pour les personnes concernées et leurs proches, conseils à l''entourage et diagramme de l''humeur."}]},{"type":"paragraph","content":[{"type":"text","text":"Documentation de l''Association Bipolaire Provence","marks":[{"type":"link","attrs":{"href":"http://assobipolaireprovence.unblog.fr/","target":null,"rel":null,"class":null}}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"La phase dépressive"}]},{"type":"paragraph","content":[{"type":"text","text":"Elle peut se manifester par :"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"une tristesse intense et une perte de la capacité à éprouver du plaisir"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"une indifférence à l''environnement et de l''anxiété"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"un ralentissement de la pensée, des difficultés de concentration ou de prise de décision"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"des idées noires (dévalorisation, pessimisme), parfois des idées suicidaires"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"une diminution de l''activité et de la fatigue"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"des modifications du sommeil, de l''appétit et de la libido"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"L''hypomanie et la manie"}]},{"type":"paragraph","content":[{"type":"text","text":"Ces phases d''excitation, qui peuvent aller jusqu''à une perte du contrôle de soi, peuvent se manifester par :"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"une euphorie excessive, une irritabilité et une colère facile"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"une augmentation de l''estime de soi, un sentiment exagéré de grandeur et d''importance"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"une fuite des idées, une accélération de la pensée et une distractibilité"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"une envie de parler constamment et une hyperactivité"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"des comportements inhabituels : dépenses d''argent, prises de risques, consommation de toxiques"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"une réduction du temps de sommeil sans fatigue"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Conférences en vidéo"}]},{"type":"paragraph","content":[{"type":"text","text":"Deux vidéos retenues par l''association pour approfondir le sujet. Les conférences organisées au GEM sont annoncées dans les actualités."}]},{"type":"paragraph","content":[{"type":"text","text":"La schizophrénie et les troubles bipolaires, cours de Santé Québec (YouTube)","marks":[{"type":"link","attrs":{"href":"https://www.youtube.com/watch?v=DpGc_XzHXw4","target":null,"rel":null,"class":null}}]}]},{"type":"paragraph","content":[{"type":"text","text":"TCC et troubles bipolaires (YouTube)","marks":[{"type":"link","attrs":{"href":"https://www.youtube.com/watch?v=5PN11L4wXKA","target":null,"rel":null,"class":null}}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Sites d''information"}]},{"type":"paragraph","content":[{"type":"text","text":"Des sites reconnus pour s''informer sur la santé mentale, les troubles psychiques et les droits des personnes."}]},{"type":"paragraph","content":[{"type":"text","text":"Psycom, information sur la santé mentale","marks":[{"type":"link","attrs":{"href":"https://www.psycom.org/","target":null,"rel":null,"class":null}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Relief (anciennement Revivre), anxiété, dépression et bipolarité","marks":[{"type":"link","attrs":{"href":"https://relief.ca/","target":null,"rel":null,"class":null}}]}]},{"type":"paragraph","content":[{"type":"text","text":"PsychoMédia, actualités en psychologie et santé","marks":[{"type":"link","attrs":{"href":"https://www.psychomedia.qc.ca/","target":null,"rel":null,"class":null}}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Sorties culturelles et sportives"}]},{"type":"paragraph","content":[{"type":"text","text":"Grâce à Culture et Sport Solidaires 34, les adhérents peuvent accéder gratuitement à des cours de sport à l''année, encadrés par des éducateurs sportifs, et à des sorties culturelles : théâtre, musique, danse, cinéma, expositions, musées, sorties nature. Pour en bénéficier, adressez-vous aux animatrices de Janus34."}]},{"type":"paragraph","content":[{"type":"text","text":"Le MCSA 34 propose aussi des cours de sport adapté à l''année, et des classeurs disponibles au GEM rassemblent d''autres idées de sorties."}]},{"type":"paragraph","content":[{"type":"text","text":"Culture et Sport Solidaires 34","marks":[{"type":"link","attrs":{"href":"https://www.cultureetsportsolidaires34.fr/","target":null,"rel":null,"class":null}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Montpellier Culture Sport Adapté (MCSA34)","marks":[{"type":"link","attrs":{"href":"https://www.mcsa34.com/","target":null,"rel":null,"class":null}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Agenda de l''office de tourisme de Montpellier","marks":[{"type":"link","attrs":{"href":"https://www.montpellier-tourisme.fr/","target":null,"rel":null,"class":null}}]}]}]}'::jsonb),
  ('mentions-legales', 'Mentions légales', 'Les informations sur l''éditeur et l''hébergeur du site de Janus34.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Éditeur du site"}]},{"type":"paragraph","content":[{"type":"text","text":"Ce site est édité par l''association Janus34."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Association Janus34, Groupe d''Entraide Mutuelle, association loi 1901"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Adresse : 405 rue des Grèzes, 34070 Montpellier"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Téléphone : 04 67 04 87 68"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Responsable de la publication"}]},{"type":"paragraph","content":[{"type":"text","text":"La responsabilité de la publication est assurée par la présidence de l''association Janus34."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Hébergement"}]},{"type":"paragraph","content":[{"type":"text","text":"Le site est hébergé par :"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Vercel Inc."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"440 N Barranca Avenue #4133, Covina, CA 91723, États-Unis"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"vercel.com","marks":[{"type":"link","attrs":{"href":"https://vercel.com/","target":null,"rel":null,"class":null}}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Propriété intellectuelle"}]},{"type":"paragraph","content":[{"type":"text","text":"Les textes, le logo et les documents de l''association publiés sur ce site appartiennent à Janus34. Les documents d''information de tiers restent la propriété de leurs auteurs. Toute reproduction sans autorisation est interdite, sauf usage personnel et non commercial."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Limites de responsabilité"}]},{"type":"paragraph","content":[{"type":"text","text":"Les informations de ce site sont fournies à titre indicatif. Janus34 s''efforce de les tenir à jour mais ne peut garantir leur exactitude ni leur pertinence. Les informations sur les troubles bipolaires ne remplacent pas l''avis d''un professionnel de santé."}]},{"type":"paragraph","content":[{"type":"text","text":"Les liens vers d''autres sites sont proposés pour information. Janus34 n''est pas responsable de leur contenu."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Droit applicable"}]},{"type":"paragraph","content":[{"type":"text","text":"Ce site est soumis au droit français. En cas de litige n''ayant pu faire l''objet d''un accord amiable, les tribunaux français sont seuls compétents."}]}]}'::jsonb),
  ('confidentialite', 'Confidentialité', 'Comment Janus34 traite les données personnelles sur ce site, conformément au Règlement général sur la protection des données (RGPD).', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Formulaires de contact et de rappel"}]},{"type":"paragraph","content":[{"type":"text","text":"Lorsque vous écrivez à l''association depuis le formulaire de contact, Janus34 enregistre votre nom, adresse e-mail, objet et message. Lorsque vous demandez à être rappelé, Janus34 enregistre votre prénom ou nom, votre numéro de téléphone et le moment où vous joindre. Ces informations servent uniquement à répondre à votre demande."}]},{"type":"paragraph","content":[{"type":"text","text":"Seule l''équipe de Janus34 y a accès, depuis l''espace d''administration du site. Une copie de chaque demande est aussi envoyée à la boîte e-mail de l''équipe par le service d''envoi Resend."}]},{"type":"paragraph","content":[{"type":"text","text":"Les messages sont supprimés une fois la demande traitée, et au plus tard au bout de 3 ans."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Navigation sur le site"}]},{"type":"paragraph","content":[{"type":"text","text":"Le site ne dépose aucun cookie publicitaire ni de mesure d''audience. Il compte les visites avec Cloudflare Web Analytics, un outil sans cookie qui n''enregistre rien sur votre appareil. Comme pour tout site web, l''hébergeur Vercel enregistre des journaux techniques (adresse IP, page demandée, date et heure) nécessaires à la sécurité et au bon fonctionnement du service."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Espace d''administration"}]},{"type":"paragraph","content":[{"type":"text","text":"L''espace d''administration, réservé à l''équipe de Janus34, utilise des cookies techniques de connexion. Les comptes de l''équipe, les contenus publiés et les messages reçus sont hébergés par le service Supabase."}]},{"type":"paragraph","content":[{"type":"text","text":"Une copie de sauvegarde du site (contenus, comptes de l''équipe et messages) est faite chaque nuit et conservée 90 jours dans un espace privé du service GitHub."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Vidéos et carte"}]},{"type":"paragraph","content":[{"type":"text","text":"Les vidéos (YouTube, Vimeo) et la carte (Google Maps) ne se chargent que si vous cliquez dessus. Ces services peuvent alors déposer des cookies et recevoir votre adresse IP, selon leurs propres règles de confidentialité. Avant le clic, seule l''image d''aperçu d''une vidéo YouTube est chargée depuis ses serveurs, sans cookie."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Vos droits"}]},{"type":"paragraph","content":[{"type":"text","text":"Vous disposez d''un droit d''accès, de rectification, d''effacement et d''opposition sur les données qui vous concernent. Pour les exercer, contactez Janus34 par téléphone au 04 67 04 87 68 ou par courrier au 405 rue des Grèzes, 34070 Montpellier."}]},{"type":"paragraph","content":[{"type":"text","text":"Si vous estimez que vos droits ne sont pas respectés, vous pouvez adresser une réclamation à la CNIL."}]},{"type":"paragraph","content":[{"type":"text","text":"Adresser une plainte à la CNIL","marks":[{"type":"link","attrs":{"href":"https://www.cnil.fr/fr/plaintes","target":null,"rel":null,"class":null}}]}]}]}'::jsonb)
